-- My Social Data Space: append-only MVP mailbox.
--
-- The mobile/web app receives only a publishable key. No service-role secret is
-- embedded in a client. PostgreSQL stores opaque signed events; every pod checks
-- the Ed25519 signature derived from author_did before writing to Drift.

create table if not exists public.mds_relay_events (
  sequence bigint generated always as identity primary key,
  event_id text not null unique,
  kind text not null check (kind in ('post', 'tombstone')),
  space_id text not null check (char_length(space_id) between 1 and 160),
  post_id text not null check (char_length(post_id) between 1 and 200),
  author_did text not null check (
    char_length(author_did) between 40 and 180
    and author_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  event_at timestamptz not null,
  payload jsonb not null check (octet_length(payload::text) <= 262144),
  signature text not null check (char_length(signature) between 40 and 180),
  inserted_at timestamptz not null default now()
);

create index if not exists mds_relay_events_space_sequence_idx
  on public.mds_relay_events (space_id, sequence);

alter table public.mds_relay_events enable row level security;
revoke all on public.mds_relay_events from anon, authenticated;
grant select, insert on public.mds_relay_events to anon, authenticated;
grant usage, select on sequence public.mds_relay_events_sequence_seq to anon, authenticated;

drop policy if exists "mds relay events are publicly readable" on public.mds_relay_events;
create policy "mds relay events are publicly readable"
  on public.mds_relay_events for select
  to anon, authenticated
  using (true);

drop policy if exists "mds relay events are append only" on public.mds_relay_events;
create policy "mds relay events are append only"
  on public.mds_relay_events for insert
  to anon, authenticated
  with check (
    inserted_at <= now() + interval '1 minute'
    and event_at <= now() + interval '1 day'
    and event_at >= now() - interval '10 years'
  );

create table if not exists public.mds_relay_spaces (
  space_id text primary key,
  member_count integer not null default 0 check (member_count >= 0),
  definition jsonb not null check (octet_length(definition::text) <= 262144),
  updated_at timestamptz not null default now()
);

alter table public.mds_relay_spaces enable row level security;
revoke all on public.mds_relay_spaces from anon, authenticated;
grant select on public.mds_relay_spaces to anon, authenticated;

drop policy if exists "mds relay spaces are publicly readable" on public.mds_relay_spaces;
create policy "mds relay spaces are publicly readable"
  on public.mds_relay_spaces for select
  to anon, authenticated
  using (true);

