-- ============================================================
-- supabase/migrations/202608020001_remove_fabricated_catalog_state.sql
-- ============================================================
-- Remove social state that older development seeds invented for bundled topic
-- structures. This is intentionally narrow: a count is reset only when it still
-- equals the exact old placeholder, and a steward is removed only when it still
-- equals the exact fictional DID. Real activity or a real founder survives.
with legacy(space_id, placeholder_members, placeholder_steward) as (
  values
    ('space_field_recordings_01', 412, 'did:mds:steward_quiet'),
    ('space_macro_kitchen_01', 2071, 'did:mds:steward_macro'),
    ('space_powerlifting_01', 1284, 'did:mds:steward_iron'),
    ('space_coffee_01', 863, 'did:mds:steward_crema')
)
update public.mds_relay_spaces as spaces
set
  member_count = case
    when spaces.member_count = legacy.placeholder_members then 0
    else spaces.member_count
  end,
  definition = (
    case
      when spaces.definition ->> 'steward_id' = legacy.placeholder_steward
        then spaces.definition - 'steward_id'
      else spaces.definition
    end
  ) - 'member_count' - 'post_count',
  updated_at = now()
from legacy
where spaces.space_id = legacy.space_id;

