-- supabase/migrations/202608030001_signed_authored_topics.sql
-- ============================================================
-- User-authored topic definitions are append-only and client-verifiable.
--
-- `mds_relay_spaces` remains the operator-curated catalog. Giving the
-- publishable client key UPDATE access to it would let any installation replace
-- any topic. Authored definitions therefore use immutable signed events, just
-- like posts and tombstones; every receiving pod verifies the steward DID
-- before the definition reaches local storage.

create table if not exists public.mds_relay_space_events (
  sequence bigint generated always as identity primary key,
  event_id text not null unique,
  space_id text not null check (
    char_length(space_id) between 1 and 160
    and space_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  ),
  version integer not null check (version between 1 and 1000000),
  steward_did text not null check (
    char_length(steward_did) between 40 and 180
    and steward_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  definition jsonb not null check (octet_length(definition::text) <= 262144),
  signature text not null check (char_length(signature) between 40 and 180),
  inserted_at timestamptz not null default now()
);

create index if not exists mds_relay_space_events_sequence_idx
  on public.mds_relay_space_events (sequence desc);

create index if not exists mds_relay_space_events_space_version_idx
  on public.mds_relay_space_events (space_id, version desc);

