-- ============================================================
-- supabase/migrations/202608050001_reversible_topic_discovery.sql
-- ============================================================
-- Authored-topic publication is reversible without deleting its audit trail.
--
-- Old rows remain version-1 `publish` events at audience revision zero. New
-- clients sign action, monotonic audience revision and event time together with
-- the full definition. A later unlisting therefore outranks a delayed publish;
-- republishing requires a higher audience revision.

alter table public.mds_relay_space_events
  add column if not exists event_version integer not null default 1
    check (event_version in (1, 2)),
  add column if not exists action text not null default 'publish'
    check (action in ('publish', 'unlist')),
  add column if not exists publication_revision integer not null default 0
    check (publication_revision between 0 and 1000000000),
  add column if not exists event_at timestamptz;

alter table public.mds_relay_space_events
  drop constraint if exists mds_relay_space_events_reversible_shape;

alter table public.mds_relay_space_events
  add constraint mds_relay_space_events_reversible_shape check (
    (event_version = 1 and action = 'publish' and publication_revision = 0)
    or
    (
      event_version = 2
      and publication_revision > 0
      and event_at is not null
    )
  );

create index if not exists mds_relay_space_events_publication_idx
  on public.mds_relay_space_events
    (space_id, publication_revision desc, action asc, version desc, sequence desc);

-- No UPDATE or DELETE permission is added. Unlisting is another immutable,
-- steward-signed event and does not claim to erase copies peers already kept.

-- ============================================================
-- supabase/migrations/202608060001_data_requests.sql
-- ============================================================
-- Data requests and their answers (REQ-44).
--
-- **Applied and checked against PostgreSQL 16 on 2026-07-31**, not only written:
-- both tables are created with row-level security on, `anon` and
-- `authenticated` hold SELECT and INSERT and nothing else, and an `anon`
-- session was refused UPDATE and DELETE on a real row. The file also re-applies
-- cleanly, so a redeploy is not a failure. What that run could *not* cover is
-- PostgREST and Storage, which is what `tool/relay_smoke.dart` is for once this
-- reaches a Supabase project.
--
-- **Two tables that the server is not asked to police, and that is the design.**
-- There are no accounts here — the client key is publishable and anonymous — so
-- this database cannot authenticate a DID and cannot be asked to show a row only
-- to the right reader. A restriction it cannot enforce is not a restriction, and
-- writing one would have been theatre.
--
-- So both guarantees live in the payload instead:
--
--  * **who asked** is an Ed25519 signature over the request's own terms,
--    verified by every receiving pod before the request is stored. A row here
--    claiming somebody else's name never reaches a screen.
--  * **who may read an answer** is settled by encryption. The response payload
--    is sealed to the exchange key the request carried, so this table may be
--    read by anybody and still means nothing to them.
--
-- Both tables are append-only for the same reason `mds_relay_space_events` is:
-- giving the publishable key UPDATE would let any installation rewrite any
-- request — including the reply address, which is the one field worth stealing.

create table if not exists public.mds_relay_data_requests (
  sequence bigint generated always as identity primary key,
  request_id text not null unique,
  space_id text not null check (
    char_length(space_id) between 1 and 160
    and space_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  ),
  requester_did text not null check (
    char_length(requester_did) between 40 and 180
    and requester_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  -- The whole signed envelope, including the signature the client checks.
  payload jsonb not null check (octet_length(payload::text) <= 65536),
  -- Kept as a column as well as inside the payload so a closed request can be
  -- filtered out server-side instead of downloaded and discarded.
  expires_at timestamptz,
  inserted_at timestamptz not null default now()
);

create index if not exists mds_relay_data_requests_space_idx
  on public.mds_relay_data_requests (space_id, sequence desc);

alter table public.mds_relay_data_requests enable row level security;
revoke all on public.mds_relay_data_requests from anon, authenticated;
grant select, insert on public.mds_relay_data_requests to anon, authenticated;
grant usage, select on sequence public.mds_relay_data_requests_sequence_seq
  to anon, authenticated;

drop policy if exists "mds data requests are publicly readable"
  on public.mds_relay_data_requests;
create policy "mds data requests are publicly readable"
  on public.mds_relay_data_requests for select
  to anon, authenticated
  using (true);

drop policy if exists "mds data requests are append only"
  on public.mds_relay_data_requests;
create policy "mds data requests are append only"
  on public.mds_relay_data_requests for insert
  to anon, authenticated
  with check (inserted_at <= now() + interval '1 minute');

-- Answers.
--
-- `payload` holds a sealed envelope and nothing else legible: no entry ids, no
-- field names, no values. `responder_did` is in the clear because the requester
-- has to count distinct contributors, and because a request names its author
-- too — asymmetry there would be the first step back to a surveillance
-- relationship.
create table if not exists public.mds_relay_data_request_responses (
  sequence bigint generated always as identity primary key,
  response_id text not null unique,
  request_id text not null check (char_length(request_id) between 1 and 160),
  responder_did text not null check (
    char_length(responder_did) between 40 and 180
    and responder_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  payload jsonb not null check (octet_length(payload::text) <= 1048576),
  inserted_at timestamptz not null default now()
);

create index if not exists mds_relay_data_request_responses_request_idx
  on public.mds_relay_data_request_responses (request_id, sequence desc);

alter table public.mds_relay_data_request_responses enable row level security;
revoke all on public.mds_relay_data_request_responses from anon, authenticated;
grant select, insert on public.mds_relay_data_request_responses to anon, authenticated;
grant usage, select on sequence public.mds_relay_data_request_responses_sequence_seq
  to anon, authenticated;

-- Readable by anybody, and that is safe *only* because the payload is sealed.
-- If a future change ever puts anything legible in this table, this policy is
-- the line that has to change with it.
drop policy if exists "mds request answers are publicly readable"
  on public.mds_relay_data_request_responses;
create policy "mds request answers are publicly readable"
  on public.mds_relay_data_request_responses for select
  to anon, authenticated
  using (true);

drop policy if exists "mds request answers are append only"
  on public.mds_relay_data_request_responses;
create policy "mds request answers are append only"
  on public.mds_relay_data_request_responses for insert
  to anon, authenticated
  with check (inserted_at <= now() + interval '1 minute');

-- No UPDATE or DELETE on either table. A withdrawn request stops being
-- announced by its author's client rather than being erased here, which is the
-- same best-effort shape as a tombstone: in a real peer network you can ask
-- somebody to forget something, you cannot make them.

-- ============================================================
-- supabase/migrations/202608070001_challenges.sql
-- ============================================================
-- Community contests and the entries in them (REQ-17).
--
-- **Two tables, because a contest is two different claims.** The creator signs
-- the rules once and they stay checkable for the contest's life; entering is
-- each participant's own signed claim. One table carrying both would mean
-- either the creator attesting other people's participation — the same mistake
-- as a topic signing its own member count — or a signature that the first join
-- invalidates.
--
-- Neither table asks this database to decide anything. `mds_relay_challenges`
-- holds rules that verify against the creator's DID, and
-- `mds_relay_challenge_entries` holds claims that verify against the
-- participant's. A row here that lies is refused by the receiving pod, not by a
-- policy, because an anonymous publishable key cannot authenticate a DID.
--
-- Append-only for the same reason as every other relay table: UPDATE with a
-- publishable key would let any installation rewrite any contest's measure or
-- window, which is the one thing somebody losing would most like to change.

create table if not exists public.mds_relay_challenges (
  sequence bigint generated always as identity primary key,
  challenge_id text not null unique,
  space_id text not null check (
    char_length(space_id) between 1 and 160
    and space_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  ),
  created_by text not null check (
    char_length(created_by) between 40 and 180
    and created_by ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  -- The signed envelope, minus its participant list: that is never the
  -- creator's to state, and the client strips it before publishing.
  payload jsonb not null check (octet_length(payload::text) <= 65536),
  closes_at timestamptz,
  inserted_at timestamptz not null default now()
);

create index if not exists mds_relay_challenges_space_idx
  on public.mds_relay_challenges (space_id, sequence desc);

alter table public.mds_relay_challenges enable row level security;
revoke all on public.mds_relay_challenges from anon, authenticated;
grant select, insert on public.mds_relay_challenges to anon, authenticated;
grant usage, select on sequence public.mds_relay_challenges_sequence_seq
  to anon, authenticated;

drop policy if exists "mds contests are publicly readable"
  on public.mds_relay_challenges;
create policy "mds contests are publicly readable"
  on public.mds_relay_challenges for select
  to anon, authenticated
  using (true);

drop policy if exists "mds contests are append only"
  on public.mds_relay_challenges;
create policy "mds contests are append only"
  on public.mds_relay_challenges for insert
  to anon, authenticated
  with check (inserted_at <= now() + interval '1 minute');

-- Entries.
--
-- Unique on (contest, participant) rather than on an id of its own: entering
-- twice is entering once, and the pair is what makes a retry after a dropped
-- connection the same claim instead of a second person.
create table if not exists public.mds_relay_challenge_entries (
  sequence bigint generated always as identity primary key,
  challenge_id text not null check (char_length(challenge_id) between 1 and 160),
  participant_did text not null check (
    char_length(participant_did) between 40 and 180
    and participant_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  payload jsonb not null check (octet_length(payload::text) <= 8192),
  inserted_at timestamptz not null default now(),
  unique (challenge_id, participant_did)
);

create index if not exists mds_relay_challenge_entries_challenge_idx
  on public.mds_relay_challenge_entries (challenge_id, sequence desc);

alter table public.mds_relay_challenge_entries enable row level security;
revoke all on public.mds_relay_challenge_entries from anon, authenticated;
grant select, insert on public.mds_relay_challenge_entries to anon, authenticated;
grant usage, select on sequence public.mds_relay_challenge_entries_sequence_seq
  to anon, authenticated;

drop policy if exists "mds contest entries are publicly readable"
  on public.mds_relay_challenge_entries;
create policy "mds contest entries are publicly readable"
  on public.mds_relay_challenge_entries for select
  to anon, authenticated
  using (true);

drop policy if exists "mds contest entries are append only"
  on public.mds_relay_challenge_entries;
create policy "mds contest entries are append only"
  on public.mds_relay_challenge_entries for insert
  to anon, authenticated
  with check (inserted_at <= now() + interval '1 minute');

-- No UPDATE or DELETE on either. Leaving a contest is a local decision that
-- stops this pod being scored; it does not erase the signed claim that somebody
-- entered, any more than a tombstone erases a post from a pod that already has
-- it.

-- ============================================================
-- supabase/migrations/202608080001_remove_untouched_fixture_topics.sql
-- ============================================================
-- Remove the four example structures that an older deployment guide told
-- operators to seed as though they were live communities.
--
-- This is deliberately narrower than matching an id or display name. A row is
-- removed only when:
--   * its id and complete canonical JSONB fingerprint are the generated fixture;
--   * it still has no measured members; and
--   * nobody has published signed authored history for that id.
--
-- An operator revision, a real authored publication, or even one changed field
-- therefore survives. `md5(text)` is used only as an exact data fingerprint,
-- never as an authentication primitive.
with fixture(space_id, definition_fingerprint) as (
  values
    ('space_coffee_01', '1661bc9d4dbbb898887d60c7eed23fa4'),
    ('space_field_recordings_01', 'a53176a908b4737b6afeb1b531385097'),
    ('space_macro_kitchen_01', '9f9455e61d1c8a8b28351fb4c1c32d96'),
    ('space_powerlifting_01', '85b07718de213929babccc3de6875602')
)
delete from public.mds_relay_spaces as spaces
using fixture
where spaces.space_id = fixture.space_id
  and spaces.member_count = 0
  and md5(spaces.definition::text) = fixture.definition_fingerprint
  and not exists (
    select 1
    from public.mds_relay_space_events as authored
    where authored.space_id = spaces.space_id
  );

