-- supabase/migrations/202608090001_message_reactions.sql
-- ============================================================
-- Reactions to conversation messages travel exactly as post engagements do:
-- signed, append-only, actor-scoped events. The server stores and serves; every
-- receiving pod verifies the signature and target before Drift sees the row.

alter table public.mds_relay_events
  drop constraint if exists mds_relay_events_kind_check;

alter table public.mds_relay_events
  add constraint mds_relay_events_kind_check
  check (kind in ('post', 'engagement', 'message', 'message_reaction', 'tombstone'));

-- ============================================================
-- supabase/migrations/202608100001_abuse_reports.sql
-- ============================================================
-- Reports travel to the operator of a configured community relay, and only
-- there. The queue is write-only for clients: anybody may file a report,
-- nobody may read the queue back, so a report cannot become a public accusation
-- or a way to enumerate what other people reported.

create table if not exists public.mds_abuse_reports (
  sequence bigint generated always as identity primary key,
  report_id text not null unique,
  subject text not null check (subject in ('post', 'message', 'account')),
  subject_id text not null check (char_length(subject_id) between 1 and 200),
  author_did text not null check (
    char_length(author_did) between 40 and 180
    and author_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  reporter_did text not null check (
    char_length(reporter_did) between 40 and 180
    and reporter_did ~ '^did:key:z[A-Za-z0-9_-]+$'
  ),
  category text not null check (category in (
    'spam_or_scam', 'harassment', 'hate_speech',
    'sexual_content', 'violence_or_illegal', 'something_else'
  )),
  space_id text not null default '' check (char_length(space_id) <= 160),
  reported_at timestamptz not null,
  signature text not null check (char_length(signature) between 40 and 180),
  inserted_at timestamptz not null default now()
);

create index if not exists mds_abuse_reports_triage_idx
  on public.mds_abuse_reports (inserted_at desc, subject_id);

alter table public.mds_abuse_reports enable row level security;
revoke all on public.mds_abuse_reports from anon, authenticated;

-- Insert only. The operator reads this queue with the service role, out of band.
grant insert on public.mds_abuse_reports to anon, authenticated;
grant usage, select on sequence public.mds_abuse_reports_sequence_seq to anon, authenticated;

drop policy if exists "anyone may file a report" on public.mds_abuse_reports;
create policy "anyone may file a report"
  on public.mds_abuse_reports for insert to anon, authenticated with check (true);

